--region init

function OverseaManageCatBallExchangePopup:InitData()
    self._quality2Count    = {}
    self._exchangeNum      = 0
    self._selectNum        = 0
    self._playerCatId2Data = {}
    self._goodsId2Data     = {}
    
    --- 如果直接从 Argument.parameters 取列表的话会直接Copy一份数据 
    --self.controller.Argument.parameters
    ---@type CatEggComponent
    local eggComponent     = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local playerCatId2Dojo = eggComponent:GetCats()

    ---@type MaidCoffeeComponent
    local maidCoffeeComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local staffId2Index       = maidCoffeeComponent:GetInServiceCats()
    local dataList = {}
    --- 收集 显示 非主题猫 加 大类4的道具
    ---@param dojo CatEggDojo
    for i, dojo in pairs(playerCatId2Dojo) do
        ---@type MaidCoffeeCatRollConfigVo
        local vo      = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(dojo.catId)
        local quality = vo.quality
        local dojoId  = checkNumber(dojo.id)
        if quality ~= MaidCoffeeConstants.CatBallQuality.Theme and dojo.locked == 0 and staffId2Index[dojoId] == nil then
            dojo.id = checkNumber(dojo.id)
            local catData = { vo = vo, catData = dojo, quality = quality}
            table.insert(dataList, catData)
        end
    end

    local convertBackpack = eggComponent:GetConvertBackpack()
    for goodsId, goodsNum in pairs(convertBackpack) do
        goodsNum = checkNumber(goodsNum)
        if goodsNum > 0 then
            ---@type GoodsVo
            local vo = goodsConfMgr:GetGoodsVoById(goodsId)
            table.insert(dataList, { vo = vo, quality = MaidCoffeeConstants.CatBallQuality.Theme, goodsNum = goodsNum, selectNum = 0})
        end
    end

    if next(dataList) ~= nil then
        table.sort(dataList, function(a, b)
            return a.quality > b.quality
        end)

    end
    
    self._dataList = dataList

    self._goodsId       = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.ExchangeGoodsId).num)
    self._exchangeLimit = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.ExchangeCatBallLimit).num)
end

