end

function OverseaManageCatBallExchangePopup:FreshFilterNodes()
    local parent = self.Filter
    local childCount = parent.childCount
    for i = 1, childCount do
        ---@type UnityEngine.UI.Toggle
        local toggle = self._filterNodes[i]
        if isNull(toggle) then
            local child = parent:GetChild(i - 1)
            toggle = child.gameObject:GetComponent(ToggleType)
            toggle.isOn = false
            self._filterNodes[i] = toggle
            SetToggleValueChanged(toggle, function(value)
                if value then
                    self._quality2IsSelect[i] = true
                else
                    self._quality2IsSelect[i] = nil
                end

                self:OneKeySelectByQuality(i, value)
                self:FreshUI()

            end)
        end
        
    end
end

---SelectDataByQuality
---通过品质一键选择选择
---@param quality number
---@param isSelect boolean
function OverseaManageCatBallExchangePopup:OneKeySelectByQuality(quality, isSelect)
    if isSelect then
        local exchangeLimit = self._exchangeLimit
        if self._selectNum >= exchangeLimit then
            return
        end
        local leftCanSelectNum = exchangeLimit - self._selectNum
        for i, data in ipairs(self._dataList) do
            if quality == data.quality then
                local goodsNum = data.goodsNum
                local isGoods  = goodsNum ~= nil
                if isGoods then
                    local times = math.min(goodsNum - data.selectNum, leftCanSelectNum)
                    leftCanSelectNum = leftCanSelectNum - times
                    self:FreshGoodSelectNum(data, times)
                elseif self._playerCatId2Data[data.catData.id] == nil then
                    self:FreshCatSelectNum(data, 1)
                end
                if self._selectNum >= exchangeLimit then
                    return
                end
            end
        end
    else
        if checkNumber(self._quality2Count[quality]) <= 0 then
            return
        end
        
        for i, data in ipairs(self._dataList) do
            if quality == data.quality then
                local goodsNum = data.goodsNum
                local isGoods  = goodsNum ~= nil
                if isGoods then
                    self:FreshGoodSelectNum(data, -data.selectNum)
                else
                    self:FreshCatSelectNum(data, -1)
                end
                if self._selectNum == 0 then
                    return
                end
            end
        end
        
    end

end


