---FreshQuantityNode
---刷新猫球品质数量
---@param quality number
function OverseaManageCatBallExchangePopup:FreshQuantityNode(quality)
    local node  = self._quantityNodes[quality]
    local count = self._quality2Count[quality] or 0
    local child, textComp
    if node == nil then
        local parent         = self.Quantity.gameObject
        child = parent:AddChild(self.NodeQuantity.gameObject)
        local childTrans = child.transform
        local ImgQuality = childTrans:Find("ImgQuality")
        CfUtils.SetUISwitchImage(ImgQuality, quality)

        local trans      = childTrans:Find("TextNumber")
        textComp = trans.gameObject:GetComponent(TextMeshProUGUIType)
        self._quantityNodes[quality] = {child, textComp}
    else
        child, textComp = SafeUnpack(node)
    end
    local isShow = count > 0
    KTool.SetActive(child, isShow)
    if isShow then
        textComp.text = count
    end
end

