function OverseaManageCatBallExchangePopup:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(Cell)
    local node = GetLuaBehaviour(cell.gameObject, MaidCoffeeConstants.EnvPath.OverseaManageCatBallExchangeCell)

    ---@type OverseaManageCatBallExchangeCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
        nodeEnv:SetClickCb(Bind(self, self.OnClickAction))
        nodeEnv:SetLongPressCb(Bind(self, self.OnLongPressAction))
        nodeEnv:SetClickBtnReduceCb(Bind(self, self.OnClickBtnReduceAction))
        nodeEnv:SetLongPressBtnReduceCb(Bind(self, self.OnLongPressBtnReduceAction))
    else
        nodeEnv = node.Env
    end

    if nodeEnv then
        local position = index + 1
        local dataList = self._dataList
        local data = dataList[position]
        nodeEnv:FreshUI(data, self._playerCatId2Data)
    end

    return cell
end

---FreshGoodSelectNum
---@param data table
---@param env OverseaManageCatBallExchangeCell
function OverseaManageCatBallExchangePopup:FreshCellGoodSelectNum(data, times, env)
    local res = self:FreshGoodSelectNum(data, times)
    if not res then
        return
    end
    self:FreshExchangeNum()
    self:FreshSelectNum()
    env:FreshGoodSelectNum(data.selectNum)
    self:FreshQuantityNode(data.quality)
    
end

function OverseaManageCatBallExchangePopup:FreshGoodSelectNum(data, times)
    local isReduce = times < 0
    local deltaTimes
    local newSelectNum
    if isReduce then
        local maxDeltaTimes = data.selectNum * -1
        deltaTimes          = math.max(maxDeltaTimes, times)
        newSelectNum        = data.selectNum + deltaTimes
    else
        local maxDeltaTimes = data.goodsNum - data.selectNum
        deltaTimes          = math.min(maxDeltaTimes, times)
        local leftCanSelectNum = self._exchangeLimit - self._selectNum
        deltaTimes             = math.min(leftCanSelectNum, deltaTimes)
        newSelectNum        = data.selectNum + deltaTimes
    end
    
    if newSelectNum > self._exchangeLimit or deltaTimes == 0 then
        return false
    end

    data.selectNum = newSelectNum
    ---@type GoodsVo
    local vo = data.vo
    local deltaExchangeNum = deltaTimes * vo.effectNum
    self._goodsId2Data[vo.id] = data.selectNum > 0 and data or nil
    
    self._exchangeNum = self._exchangeNum + deltaExchangeNum
    self._selectNum = self._selectNum + deltaTimes
    self._quality2Count[data.quality] = (self._quality2Count[data.quality] or 0) + deltaTimes
    
    return true
end

function OverseaManageCatBallExchangePopup:FreshCatSelectState(data, env)
    local res, isSelect = self:FreshCatSelectNum(data)
    if not res then
        return
    end
    env:FreshSelectState(isSelect)
    self:FreshExchangeNum()
    self:FreshSelectNum()
    self:FreshQuantityNode(data.quality)
end

function OverseaManageCatBallExchangePopup:FreshCatSelectNum(data, customSelectNum)
    ---@type CatEggDojo
    local catData     = data.catData
    local playerCatId = checkNumber(catData.id)
    
    local isSelect, selectNum
    if customSelectNum then
        selectNum = customSelectNum
        isSelect = customSelectNum > 0
        if not isSelect and self._playerCatId2Data[playerCatId] == nil then
            return
        end
    else
        --- 以前没数据则当前是选择状态
        isSelect = self._playerCatId2Data[playerCatId] == nil
        selectNum = isSelect and 1 or -1
    end
    
    local newSelectNum = self._selectNum + selectNum
    if isSelect and newSelectNum > self._exchangeLimit then
        return false
    end

    self._playerCatId2Data[playerCatId] = isSelect and data or nil
    local deltaExchangeNum = selectNum * (data.vo.changeNum or data.vo.effectNum)
    self._exchangeNum = self._exchangeNum + deltaExchangeNum
    self._selectNum = self._selectNum + selectNum
    self._quality2Count[data.quality] = (self._quality2Count[data.quality] or 0) + selectNum
    
    return true, isSelect
end

