    else
        self:FreshCatSelectState(data, env, true)
        
    end
end

local function CalcTimes(durationSeconds, intervalTime, scale)
    return checkInt(durationSeconds / intervalTime / scale)
end

---OnLongPressAction
---@param buttonLongPress Engine.UI.ButtonLongPress
---@param durationSeconds number
---@param data table
---@param isGoods boolean
function OverseaManageCatBallExchangePopup:OnLongPressAction(buttonLongPress, durationSeconds, data, isGoods, env)
    if isGoods then
        local intervalTime    = buttonLongPress.intervalTime
        local times           = CalcTimes(durationSeconds, intervalTime, 30)
        self:FreshCellGoodSelectNum(data, times, env, true)
        
    else
        self:FreshCatSelectState(data, env)
        
    end
end


---OnClickBtnReduceAction
---@param data table
---@param env OverseaManageCatBallExchangeCell
function OverseaManageCatBallExchangePopup:OnClickBtnReduceAction(data, env)
