end

---OnLongPressBtnReduceAction
---@param buttonLongPress Engine.UI.ButtonLongPress
---@param durationSeconds number
---@param data table
---@param env OverseaManageCatBallExchangeCell
function OverseaManageCatBallExchangePopup:OnLongPressBtnReduceAction(buttonLongPress, durationSeconds, data, env)
    local intervalTime    = buttonLongPress.intervalTime
    local times           = CalcTimes(durationSeconds, intervalTime, 30)
    self:FreshCellGoodSelectNum(data, -times, env)
end

function OverseaManageCatBallExchangePopup:OnClickFontStyleButtonAction()
    if next(self._goodsId2Data) == nil and next(self._playerCatId2Data) == nil then
        GameUtils.Toast(localize("请选择要转换的猫球"))
        return
    end
    local goodsId2Data     = self._goodsId2Data
    --print(table.toString(goodsId2Data))
    
    local goods, consumes
    for i, v in pairs(goodsId2Data) do
        local num = v.selectNum
        if num > 0 then
            goods = goods or {}
            goods[tostring(i)] = num
            consumes = consumes or {}
            table.insert(consumes, {goodsId = i, goodsNum = -1 * num})
        end
    end

    local playerCardIds
    local playerCatId2Data = self._playerCatId2Data
    for i, v in pairs(playerCatId2Data) do
        playerCardIds = playerCardIds or {}
        table.insert(playerCardIds, i)
    end
    
    local interface = Interfaces.MaidCoffeeCatRecycle
    local requestData = {}
    if playerCardIds then
        requestData.playerCatId = table.concat(playerCardIds, ",")
    else
        requestData.playerCatId = ""
    end
    if goods then
        requestData.goods = table.serialize(goods)
    else
        requestData.goods = ""
    end
    
    GameUtils.Request(interface, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = response.data
        local rewards = data.rewards
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        if playerCardIds then
            eggComponent:RecycleCatEgg(playerCardIds)
        end
        
        ---回收要转换的背包数据
        local convertBackpack = eggComponent:GetConvertBackpack()
        for goodsId, goodsNum in pairs(convertBackpack) do
            local selectData = goodsId2Data[checkNumber(goodsId)]
            if selectData then
                convertBackpack[goodsId] = convertBackpack[goodsId] - selectData.selectNum 
            end
        end
        
        GoodsUtils.DrawRewards(rewards)

        CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = rewards}, nil, false)
        Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, interface, requestData)

        self:InitData()
        for i, value in pairs(self._quality2IsSelect) do
            if value then
                self:OneKeySelectByQuality(i, value)
            end

        end
        self:FreshUI()
    end)
    
end

function OverseaManageCatBallExchangePopup:OnClickBtnCloseAction()
    CfUtils.DialogClose(Constants.UITypeIds.OverseaManageCatballExchangePopup)
end
